using System;using System.Runtime.InteropServices;using SolidWorks.Interop.sldworks;
public static class SWProbeV5{public static void Run(string root,string mode){var app=(ISldWorks)Marshal.GetActiveObject("SldWorks.Application");var m=(ModelDoc2)app.ActiveDoc;Console.WriteLine("DOC "+m.GetTitle());var d=(DrawingDoc)m;var v=(View)d.GetFirstView();while(v!=null){Console.WriteLine("VIEW "+v.GetName2());var ns=(object[])v.GetNotes();if(ns!=null)foreach(Note n in ns){var a=(Annotation)n.GetAnnotation();Console.WriteLine("NOTE "+n.GetText().Replace('\n',' ')+" POS "+string.Join(";",(double[])a.GetPosition()));}v=(View)v.GetNextView();}}}
